    *   'MESH:C531777': {'cui': 'MESH:C531777', 'name': 'Islet cell tumor syndrome', 'types': 'Disease', 'aliases': 'Bilateral pheochromocytoma and islet cell adenoma of the pancreas|Chromaffinoma|Familial islet cell tumors|Familial pheochromocytoma', 'definition': ''}
