    *   'MESH:D006445': {'cui': 'MESH:D006445', 'name': 'Hemoglobin C Disease', 'types': 'Disease', 'aliases': 'C Disease, Hemoglobin|C Diseases, Hemoglobin|Hemoglobin-C Disease|Hemoglobin C Diseases|Hemoglobin-C Diseases', 'definition': 'A disease characterized by compensated hemolysis with a normal hemoglobin level or a mild to moderate anemia. There may be intermittent abdominal discomfort, splenomegaly, and slight jaundice.'}
