*   'MESH:D000795': {'cui': 'MESH:D000795', 'name': 'Fabry Disease', 'types': 'Disease', 'aliases': "alpha Galactosidase A Deficiency|alpha-Galactosidase A Deficiency|alpha Galactosidase A Deficiency Disease|alpha-Galactosidase A Deficiency Disease|Anderson Fabry Disease|Anderson-Fabry Disease|Angiokeratoma Corporis Diffusum|Angiokeratoma Diffuse|Angiokeratoma, Diffuse|Ceramide Trihexosidase Deficiency|CERAMIDE TRIHEXOSIDASE DEFICIENCY FABRY DISEASE, CARDIAC VARIANT, INCLUDED|Deficiency, alpha-Galactosidase A|Deficiency, Ceramide Trihexosidase|Deficiency, GLA|Diffuse Angiokeratoma|Fabry's Disease|GLA Deficiency|Hereditary Dystopic Lipidosis|Lipidosis, Hereditary Dystopic", 'definition': 'An X-linked inherited metabolic disease caused by a deficiency of lysosomal ALPHA-GALACTOSIDASE A. It is characterized by intralysosomal accumulation of globotriaosylceramide and other GLYCOSPHINGOLIPIDS in blood vessels throughout the body leading to multi-system complications including renal, cardiac, cerebrovascular, and skin disorders.'}
*   'MESH:D000075262': {'cui': 'MESH:D000075262', 'name': 'Hypoadrenocorticism, Familial', 'types': 'Disease', 'aliases': 'Addison Disease, X Linked|Addison Disease, X-Linked|Adrenal Hypoplasia, Congenital|Adrenal Hypoplasia, Congenital, with Hypogonadotropic Hypogonadism|Adrenal Hypoplasia, X-linked|AHC|AHCH|AHC WITH HHG|AHC with Isolated Gonadotropin Deficiency|AHX|Complex Glycerol Kinase Deficiency|Congenital Adrenal Hypoplasia|Congenital Adrenal Hypoplasias|Cytomegalic Adrenocortical Hypoplasia|Cytomegalic Adrenocortical Hypoplasias|Familial Hypoadrenocorticism|Familial Hypoadrenocorticisms|Familial X linked Addison Disease|Familial X-linked Addison Disease|Hypoadrenocorticisms, Familial|Hypoplasia, Congenital Adrenal|X-Linked Addison Disease|X linked Adrenal Hypoplasia|X-linked Adrenal Hypoplasia|X linked Congenital Adrenal Hypoplasia|X-linked Congenital Adrenal Hypoplasia|Xp21 Contiguous Gene Deletion Syndrome', 'definition': 'Hereditary forms of Addison disease that may exhibit autosomal recessive or X-linked  inheritance. They are characterized by severe neurological symptoms, APNEA;  and death in infancy. OMIM: 240200'}
*   'MESH:D039682': {'cui': 'MESH:D039682', 'name': 'HIV-Associated Lipodystrophy Syndrome', 'types': 'Disease', 'aliases': 'HIV Associated Lipodystrophy|HIV-Associated Lipodystrophy|HIV Associated Lipodystrophy Syndrome|HIV Lipodystrophy Syndrome|Lipodystrophy, HIV-Associated|Lipodystrophy Syndrome, HIV|Lipodystrophy Syndrome, HIV-Associated', 'definition': 'Defective metabolism leading to fat maldistribution in patients infected with HIV. The etiology appears to be multifactorial and probably involves some combination of infection-induced alterations in metabolism, direct effects of antiretroviral therapy, and patient-related factors.'}
*   'MESH:D052456': {'cui': 'MESH:D052456', 'name': 'Hypoalphalipoproteinemias', 'types': 'Disease', 'aliases': 'alpha Lipoprotein Deficiency Disease, Familial|alpha-Lipoprotein Deficiency Disease, Familial|alpha Lipoproteinemia, Hypo|Familial alpha Lipoprotein Deficiency Disease|Familial alpha-Lipoprotein Deficiency Disease|FAMILIAL HDL DEFICIENCY|Familial High Density Lipoprotein Deficiency Disease|Familial High-Density Lipoprotein Deficiency Disease|Familial Hypoalphalipoproteinemia|Familial Hypoalphalipoproteinemias|FHA|FHD|HDL Cholesterol, Low Serum|HDL CHOLESTEROL, LOW SERUM;HDLC HIGH DENSITY LIPOPROTEIN CHOLESTEROL LEVEL QUANTITATIVE TRAIT LOCUS 13, INCLUDED|HDLCQ13, INCLUDED|HDLD|HDL Lipoprotein Deficiency Disease|HIGH DENSITY LIPOPROTEIN DEFICIENCY|High Density Lipoprotein Deficiency Disease, Familial|High-Density Lipoprotein Deficiency Disease, Familial|Hypoalphalipoproteinemia|Hypo alpha Lipoproteinemia|Hypoalphalipoproteinemia, Familial|Hypoalphalipoproteinemia, Primary|HYPOALPHALIPOPROTEINEMIA, PRIMARY, 1|Hypo alpha Lipoproteinemias|Hypoalphalipoproteinemias, Familial|Hypoalphalipoproteinemias, Primary|Lipoprotein Deficiency Disease, HDL, Familial|Lipoproteinemia, Hypo alpha|Lipoproteinemias, Hypo alpha|Primary Hypoalphalipoproteinemias', 'definition': 'Conditions with abnormally low levels of ALPHA-LIPOPROTEINS (high-density lipoproteins) in the blood. Hypoalphalipoproteinemia can be associated with mutations in genes encoding APOLIPOPROTEIN A-I; LECITHIN CHOLESTEROL ACYLTRANSFERASE; and ATP-BINDING CASSETTE TRANSPORTERS.'}
*   'MESH:D013167': {'cui': 'MESH:D013167', 'name': 'Spondylitis, Ankylosing', 'types': 'Disease', 'aliases': "Ankylosing Spondylarthritides|Ankylosing Spondylarthritis|Ankylosing Spondylitis|ANKYLOSING SPONDYLITIS, SUSCEPTIBILITY TO|Ankylosing Spondyloarthritides|Ankylosing Spondyloarthritis|Bechterew Disease|Bechterew's Disease|Bechterews Disease|BECHTEREW SYNDROME|Marie Struempell Disease|Marie-Struempell Disease|MARIE-STRUMPELL SPONDYLITIS|Rheumatoid Spondylitis|SPDA1|Spondylarthritides, Ankylosing|Spondylarthritis Ankylopoietica|Spondylarthritis, Ankylosing|Spondylitis Ankylopoietica|Spondylitis, Rheumatoid|Spondyloarthritides, Ankylosing|Spondyloarthritis Ankylopoietica|Spondyloarthritis, Ankylosing|SPONDYLOARTHROPATHY, SUSCEPTIBILITY TO, 1", 'definition': 'A chronic inflammatory condition affecting the axial joints, such as the SACROILIAC JOINT and other intervertebral or costovertebral joints. It occurs predominantly in young males and is characterized by pain and stiffness of joints (ANKYLOSIS) with inflammation at tendon insertions.'}
*   'MESH:C538220': {'cui': 'MESH:C538220', 'name': 'Dermatoleukodystrophy', 'types': 'Disease', 'aliases': '', 'definition': ''}
